/**
 * Cap enforcement side-effects (CONDUCTOR "Run lifecycle":
 * "`spend_cap_usd_per_ticket` OR `tokens_cap_per_ticket` hit →
 * `run_killed` + `blocked` reason").
 *
 * Mid-run: kill the pid (adapter.control), mark the run `killed`,
 * emit `run_killed` + `blocked` events (notifications are generated by
 * the store per DB-SCHEMA), and set the ticket to `blocked` with the
 * cap name as `blocked_reason`. Idempotent — the usage stream may fire
 * several partials before the kill lands.
 */
import type { RunRow } from '@sprint-runner/core';
import { applyTicketStatus } from '../contracts.js';
import type { CapKind } from '../loop/caps.js';
import { actorOf, loadHandle, nowIso } from '../loop/deps.js';
import type { LaunchContext } from './index.js';

export async function blockTicketForCap(
  ctx: LaunchContext,
  run: RunRow,
  cap: CapKind,
): Promise<void> {
  if (ctx.killedForCap.has(run.id)) return;
  ctx.killedForCap.add(run.id);
  const { deps, ws } = ctx;
  const ts = nowIso(deps);

  // Kill the pid if the run is still live (run-end path: already dead).
  const current = await deps.store.getRun(run.id);
  if (current && ['running', 'paused', 'stalled'].includes(current.status)) {
    const handle = ctx.handles.get(run.id) ?? (await loadHandle(current));
    if (handle) {
      const adapter = deps.adapters[current.backend ?? ''];
      if (adapter) {
        await Promise.resolve(adapter.control(handle, 'kill')).catch(() => {});
      }
    }
  }

  // Kill-row + run_killed + blocked + status commit — one transaction
  // (ARCHITECTURE §4.4): a crash between the run update and the events
  // would drop the notification; a crash before the status write must
  // not leave a `killed` run with a still-live ticket.
  await deps.store.transaction(async (s) => {
    await s.updateRun(run.id, {
      status: 'killed',
      exited_at: ts,
    });
    await s.appendEvent({
      workspace: ws.name,
      ticket_id: run.ticket_id,
      ts,
      stage: run.stage,
      actor_type: 'runner',
      actor_id: actorOf(deps),
      event: 'run_killed',
      run: run.id,
      refs: [],
      data: { reason: cap },
      cost_usd: null,
      tokens_in: null,
      tokens_out: null,
      tokens_cached: null,
      usage_source: null,
      duration_s: null,
      human_minutes: null,
    });

    if (run.ticket_id) {
      await s.appendEvent({
        workspace: ws.name,
        ticket_id: run.ticket_id,
        ts,
        stage: run.stage,
        actor_type: 'runner',
        actor_id: actorOf(deps),
        event: 'blocked',
        run: run.id,
        refs: [],
        data: { reason: cap },
        cost_usd: null,
        tokens_in: null,
        tokens_out: null,
        tokens_cached: null,
        usage_source: null,
        duration_s: null,
        human_minutes: null,
      });
      // applyTicketStatus opens `store.transaction` — the tx-bound
      // store reuses the open tx (a throw aborts the whole block).
      await applyTicketStatus({
        ctx: {
          workspace: ws.name,
          rootPath: ws.rootPath,
          store: s,
          actor: actorOf(deps),
          now: () => new Date(ts),
        },
        opts: {
          ticketId: run.ticket_id,
          status: 'blocked',
          blockedReason: cap,
          run: run.id,
        },
      });
    }
  });
  ctx.onCapHit?.(run, cap);
}
